def show(res):
    if not res.ok:
        print('ERR', res.output); return
    insts = res.output['instances']
    if isinstance(insts, dict):
        print('dict keys', list(insts.keys())[:10])
        items = insts.values()
    else:
        print('list len', len(insts))
        items = insts
    rows = []
    for i in items:
        if not isinstance(i, dict):
            print('field', i); continue
        b = i.get('world_bounds_m')
        rows.append((i.get('pixel_count',0), i.get('segmentation_id'), i.get('rgb_median'), b and [round(v,3) for v in b['center']], b and [round(v,3) for v in b['min']], b and [round(v,3) for v in b['max']]))
    for row in rows:
