    r = primitives.call(name='inspect_maniskill_instance', camera_uid=cam, segmentation_id=sid)
    if not r.ok:
        print(cam, sid, 'ERR', str(r.output)[:100]); continue
    o = r.output
    b = o.get('world_bounds_m') or {}
    print(cam, sid, 'px', o.get('pixel_count'), 'rgb', [round(v) for v in o.get('rgb_median',[])],
          'c',[round(v,3) for v in b.get('center',[])], 'mn',[round(v,3) for v in b.get('min',[])],
          'mx',[round(v,3) for v in b.get('max',[])],
          'ext',[round(b['max'][k]-b['min'][k],3) for k in range(3)] if b else None)

def st():
    return primitives.call(name='observe_maniskill_control_state').output
def pnow():
    return st()['tcp_pose']['p'][0]
def qnow():
    return st()['qpos'][0]

def apply(dq, grip=0.0):
    a=[0.0]*8
    for i in range(len(dq)): a[i]=dq[i]
    a[7]=grip
    return primitives.call(name='apply_maniskill_action', action=a, repeat=1)

# estimate position Jacobian (3x7)
s=st(); p0=s['tcp_pose']['p'][0]; J=[[0.0]*7 for _ in range(3)]
base=[p0[k] for k in range(3)]
for j in range(7):
    dq=[0.0]*7; dq[j]=0.15
    apply(dq, 0.0)
    p1=pnow()
    for k in range(3): J[k][j]=(p1[k]-base[k])/0.15
    base=[p1[k] for k in range(3)]
for k in range(3): print('row',k,[round(v,3) for v in J[k]])
print('p_after_cal',[round(v,4) for v in base])

cs=st(); print('p',[round(v,4) for v in cs['tcp_pose']['p'][0]],'grip',[round(v,3) for v in cs['qpos'][0][7:]])
